def validate_delete(payload: dict[str, Any]) -> tuple[dict[str, Any], dict[str, Any]]:
    if set(payload) != {"operation", "strategy_id", "strategy_version"}:
        raise HTTPException(422, "Strategy deletion fields do not match the contract")
    identity = payload["strategy_id"]
    if not isinstance(identity, str) or not identity.startswith("sdm:") or not _ID.fullmatch(identity) or ".." in identity:
        raise HTTPException(422, "Only custom strategies can be deleted")
    version = payload["strategy_version"]
    if not isinstance(version, str) or not _VERSION.fullmatch(version):
        raise HTTPException(422, "A strategy execution version is required")
    detail = strategy_detail(identity)
    if detail["version"] != version:
        raise HTTPException(409, "Strategy version changed; read it again before deleting")
    return dict(payload), {"strategy_id": identity, "strategy_version": version, "strategy_name": detail["name"]}


def execute_delete(payload: dict[str, Any]) -> tuple[str, dict[str, Any]]:
    from src.strategy_store.models import ArtifactStatus

    store = _store()
    try:
        # Use the native store's reentrant lock so a Session cannot change the
        # artifact between this worker's version check and lifecycle update.
        with store._lock:
            clean, references = validate_delete(payload)
            artifact = _custom_asset(clean["strategy_id"])
            already_deleted = mona_deleted_strategy_version(artifact) is not None
            if not already_deleted:
                updated = store.update_status(artifact.id, ArtifactStatus.DISABLED,
                    reason=MONA_DELETED_STRATEGY_PREFIX + clean["strategy_version"])
                if updated is None:
                    raise HTTPException(404, "Strategy not found")
        result = {"status": "ok", "kind": "strategy_delete", "deleted": True,
            "strategy_id": clean["strategy_id"], "strategy_version": clean["strategy_version"],
            "already_deleted": already_deleted}
        return json.dumps(result, ensure_ascii=False), references
    except HTTPException as exc:
        result = {"status": "error", "kind": "strategy_delete", "deleted": False,
            "strategy_id": payload.get("strategy_id"), "strategy_version": payload.get("strategy_version"),
            "error_code": "strategy_version_changed" if exc.status_code == 409 else "strategy_delete_unavailable"}
        return json.dumps(result, ensure_ascii=False), {}


